import { FC, HTMLAttributes, ReactNode } from 'react';

import { QuestionCircleOutlined } from '@ant-design/icons';

import { theme, Tooltip } from 'antd';
import { TooltipPlacement } from 'antd/lib/tooltip';

interface IInfoTooltipProps extends HTMLAttributes<HTMLDivElement> {
	text: ReactNode;
	place?: TooltipPlacement;
	color?: string;
	width?: number;
	height?: number;
}

export const InfoTooltip: FC<IInfoTooltipProps> = ({
	className,
	place = 'top',
	color,
	text,
	width,
	height,
	...props
}) => {
	const {
		token: { colorTextDescription },
	} = theme.useToken();
	return (
		<Tooltip {...props} className={className} placement={place} title={text} overlayStyle={{ zIndex: 1000 }}>
			<QuestionCircleOutlined style={{ color: color || colorTextDescription, width, height }} />
		</Tooltip>
	);
};
